<script lang="ts">
  import { onMount } from 'svelte'; import { goto } from '$app/navigation';
  import { TeacherApi, readableError, type ClassRoom, type QuestionKind, type QuestionSummary, type TemplateInput } from '$lib/teacher-api'; import TeacherNav from '$lib/teacher/TeacherNav.svelte'; import '$lib/teacher/teacher.css';
  const api = new TeacherApi(); let ready = false; let busy = false; let error = ''; let notice = '';
  let classes: readonly ClassRoom[] = []; let selectedClassId = ''; let questions: readonly QuestionSummary[] = []; let questionId = '';
  let kind: QuestionKind = 'single_choice'; let prompt = ''; let optionText = 'A | 選項一\nB | 選項二'; let reference = '';
  let detail: Awaited<ReturnType<TeacherApi['question']>> | undefined;
  onMount(() => { void initialise(); });
  async function initialise(): Promise<void> { if (!await api.restoreTeacher()) { await goto('/'); return; } ready = true; await refresh(); }
  async function work(action: () => Promise<void>): Promise<void> { busy = true; error = ''; notice = ''; try { await action(); } catch (cause) { error = readableError(cause); } finally { busy = false; } }
  async function refresh(): Promise<void> { const page = await api.classes(); classes = page.items; if (!classes.some((entry) => entry.id === selectedClassId)) selectedClassId = classes[0]?.id ?? ''; questions = selectedClassId ? (await api.questions(selectedClassId)).items : []; }
  function input(): TemplateInput { const options = optionText.split('\n').map((line, index) => { const [rawId = '', ...label] = line.split('|'); const id = rawId.trim(); return { id: (label.length ? id : String(index + 1)).trim(), label: (label.length ? label.join('|') : id).trim() }; }).filter((item) => item.id && item.label); return { kind, prompt, ...(kind === 'short_text' ? {} : { options }), referenceAnswer: kind === 'multiple_choice' ? reference.split(',').map((item) => item.trim()).filter(Boolean) : reference.trim() || null }; }
  async function saveTemp(): Promise<void> { await work(async () => { await api.createTemplate(input()); notice = '已儲存暫存題目到題庫，可繼續修改或建立草稿。'; }); }
  async function buildDraft(): Promise<void> { if (!selectedClassId) { error = '請先建立或選擇班級。'; return; } await work(async () => { const draft = await api.createDraft(selectedClassId, { question: input() }); questionId = draft.id; await refresh(); notice = '已建立草稿；可讀取後開放給學生。'; }); }
  async function load(): Promise<void> { if (!questionId) { error = '請選擇題目。'; return; } await work(async () => { detail = await api.question(questionId); }); }
  async function open(): Promise<void> { if (!questionId) { error = '請選擇題目。'; return; } await work(async () => { await api.openQuestion(questionId); await load(); await refresh(); notice = '題目已開放。'; }); }
  async function close(): Promise<void> { if (!questionId) { error = '請選擇題目。'; return; } await work(async () => { await api.closeQuestion(questionId); await load(); await refresh(); notice = '題目已關閉，現在可查看具名作答。'; }); }
  async function logout(): Promise<void> { await api.logout(); await goto('/'); }
</script>
<main aria-busy={!ready}><TeacherNav current="questions" onLogout={logout}/>
{#if !ready}<p>正在確認教師登入狀態…</p>{:else}<h2>題庫與即時題</h2><div aria-live="polite">{#if notice}<p class="notice">{notice}</p>{/if}{#if error}<p class="error" role="alert">{error}</p>{/if}</div>
<div class="grid two"><section class="panel"><h3>建立題目</h3><label for="question-class">班級</label><select id="question-class" bind:value={selectedClassId} on:change={() => void work(refresh)}>{#each classes as room}<option value={room.id}>{room.name}</option>{/each}</select><label for="kind">題型</label><select id="kind" bind:value={kind}><option value="single_choice">單選</option><option value="multiple_choice">複選</option><option value="short_text">短答</option></select><label for="prompt">題目</label><textarea id="prompt" bind:value={prompt} rows="3"></textarea>{#if kind !== 'short_text'}<label for="options">選項（每行「ID | 文字」）</label><textarea id="options" bind:value={optionText} rows="4"></textarea>{/if}<label for="reference">參考答案（僅教師可見）</label><input id="reference" bind:value={reference}/><div class="actions"><button on:click={() => void saveTemp()} disabled={busy}>Save temp</button><button class="primary" on:click={() => void buildDraft()} disabled={busy}>Build draft</button></div><p class="muted">兩個按鈕均會顯示成功或驗證錯誤；Save temp 儲存至題庫，Build draft 則建立這個班級可開放的草稿。</p></section>
<section class="panel"><h3>控制即時題</h3><label for="question-id">選擇題目</label><select id="question-id" bind:value={questionId}>{#each questions as item}<option value={item.id}>{item.state}｜{item.prompt}</option>{/each}</select><div class="actions"><button on:click={() => void load()} disabled={busy}>讀取狀態</button><button class="primary" on:click={() => void open()} disabled={busy}>開放題目</button><button on:click={() => void close()} disabled={busy}>關閉題目</button></div>{#if detail}<h4>{detail.question.state}｜{detail.question.prompt}</h4>{#if 'aggregate' in detail}<p class="notice">匿名作答：{detail.aggregate.answeredStudentCount} / {detail.aggregate.eligibleStudentCount}</p>{:else}<p class="notice">已關閉：{detail.answers.length} 筆具名作答。</p><div class="table-wrap"><table><thead><tr><th>學號</th><th>姓名</th><th>答案</th></tr></thead><tbody>{#each detail.answers as answer}<tr><td>{answer.studentNumber}</td><td>{answer.displayName}</td><td>{answer.answer === undefined ? '未作答' : JSON.stringify(answer.answer)}</td></tr>{/each}</tbody></table></div>{/if}{/if}</section></div>{/if}</main>
